list_dashboards.code:
const response = await client.dashboards.listDashboards();
for (const dashboard of response.map.dashboards) {
    console.log(dashboard.id, dashboard.name, dashboard.default);
}

create_dashboard.code:
const response = await client.dashboards.createDashboard({
    name: 'Weekly',
    kpis: ['total_sales', 'total_orders', 'aov'],
});
console.log(response.map.id, response.map.name, response.map.kpis.length);

get_dashboard.code:
const response = await client.dashboards.getDashboard('3f2b8c1e-7a4d-4e29-9b1a-5c6d7e8f9a01');
console.log(response.map.name, response.map.default);
for (const section of response.map.standard_sections) {
    console.log(section.key, section.visible);
}

patch_dashboard.code:
const response = await client.dashboards.patchDashboard('3f2b8c1e-7a4d-4e29-9b1a-5c6d7e8f9a01', {
    standard_sections: [{key: 'announcement', visible: false}],
});
for (const section of response.map.standard_sections) {
    console.log(section.key, section.visible);
}
